"""Summarise an @@EVT run log: phases, per-agent model stats, step timeline."""
import json
import sys
from collections import defaultdict
from datetime import datetime

path = sys.argv[1]
mode = sys.argv[2] if len(sys.argv) > 2 else "summary"
agent_filter = sys.argv[3] if len(sys.argv) > 3 else None
events = []
other = []
for line in open(path, encoding="utf-8", errors="replace"):
    line = line.rstrip("\n").lstrip("﻿")
    i = line.find("@@EVT ")
    if i < 0:
        if line.strip():
            other.append(line)
        continue
    try:
        events.append(json.loads(line[i + 6:]))
    except ValueError:
        other.append(line[:200])

if not events:
    print("no events")
    print("\n".join(o[:300] for o in other[-40:]))
    sys.exit()
t0 = datetime.fromisoformat(events[0]["time"])


def rel(e):
    s = (datetime.fromisoformat(e["time"]) - t0).total_seconds()
    return f"{int(s // 60):02d}:{int(s % 60):02d}"


if mode == "summary":
    stats = defaultdict(lambda: defaultdict(float))
    for e in events:
        if e["type"] == "model_call":
            d, s = e["data"], stats[e["agent"]]
            s["calls"] += 1
            s["in"] += d["tokens_in"]
            s["cached"] += d["tokens_cached"]
            s["out"] += d["tokens_out"]
            s["cost"] += d["cost"]
            s["lat"] += d["latency"]
            s["maxlat"] = max(s["maxlat"], d["latency"])
    print(f"{'agent':12}{'calls':>6}{'in/call':>9}{'cached%':>8}{'out/call':>9}{'lat avg':>8}{'lat max':>8}{'cost':>8}")
    for a, s in stats.items():
        n = s["calls"]
        print(f"{a:12}{int(n):>6}{s['in'] / n:>9.0f}{100 * s['cached'] / max(1, s['in']):>8.0f}{s['out'] / n:>9.0f}{s['lat'] / n:>8.1f}{s['maxlat']:>8.1f}{s['cost']:>8.3f}")
    print("total cost", round(sum(s["cost"] for s in stats.values()), 4), "duration", rel(events[-1]))
    print("\n-- non-step events --")
    for e in events:
        if e["type"] in ("model_call", "observation", "agent_step"):
            continue
        print(rel(e), e["type"], e["agent"], json.dumps(e["data"], ensure_ascii=False, default=str)[:600])
    print("\n-- non-event lines (tail) --")
    print("\n".join(o[:300] for o in other[-15:]))
elif mode == "steps":
    for e in events:
        if agent_filter and e["agent"] != agent_filter:
            continue
        if e["type"] == "agent_step":
            d = e["data"]
            print(rel(e), e["agent"], d["step"], json.dumps(d["action"], ensure_ascii=False)[:160], "|", d["thought"][:170], "|", d["page_url"][-70:])
        elif e["type"] in ("retry", "record_added", "record_rejected", "agent_done", "dependency", "phase", "answer_frozen", "submit_step"):
            print(rel(e), e["agent"], e["type"].upper(), json.dumps(e["data"], ensure_ascii=False, default=str)[:700])
elif mode == "obs":
    # print observations for one agent between two relative minute marks
    lo, hi = float(sys.argv[4]), float(sys.argv[5])
    for e in events:
        if e["agent"] != agent_filter or e["type"] != "observation":
            continue
        s = (datetime.fromisoformat(e["time"]) - t0).total_seconds() / 60
        if lo <= s <= hi:
            print("=" * 20, rel(e), e["data"]["page_url"])
            print(e["data"]["text"][:int(sys.argv[6]) if len(sys.argv) > 6 else 6000])

