const port = Number(process.argv[2] || 9343);

for (const p of [9341, 9342, 9343, 9344]) {
  try {
    const list = await (await fetch(`http://127.0.0.1:${p}/json/list`)).json();
    console.log(p, list.map(t => `${t.type}:${t.url.slice(0, 70)}`).join("  ||  "));
  } catch (e) {
    console.log(p, "list FAIL", e.message);
  }
}

const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = targets.find(t => t.type === "page");
console.log("probing", page.url);
const ws = new WebSocket(page.webSocketDebuggerUrl);
const pending = new Map();
let next = 1;
ws.addEventListener("message", ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    pending.get(msg.id)(msg);
    pending.delete(msg.id);
  } else if (msg.method) {
    console.log("EVENT", msg.method, JSON.stringify(msg.params).slice(0, 300));
  }
});
await new Promise((resolve, reject) => {
  ws.addEventListener("open", resolve);
  ws.addEventListener("error", () => reject(new Error("ws error")));
});
