// Dev-only: replay the stuck tab's navigation outside the browser with the tab's own cookies.
// Distinguishes a server-side stall for this session from a browser-side stuck navigation.
const port = Number(process.argv[2] || 9343);
const version = await (await fetch(`http://127.0.0.1:${port}/json/version`)).json();
const ws = new WebSocket(version.webSocketDebuggerUrl);
const pending = new Map();
let next = 1;
ws.addEventListener("message", ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
});
await new Promise((resolve, reject) => { ws.addEventListener("open", resolve); ws.addEventListener("error", () => reject(new Error("ws error"))); });
function send(method, params = {}, timeoutMs = 6000) {
  const id = next++;
  return new Promise(resolve => {
    const timer = setTimeout(() => { pending.delete(id); resolve({ timeout: true }); }, timeoutMs);
    pending.set(id, msg => { clearTimeout(timer); resolve(msg.error ? { error: msg.error.message } : msg.result); });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
const got = await send("Storage.getCookies");
if (!got.cookies) { console.log("getCookies:", JSON.stringify(got)); process.exit(1); }
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const pageUrl = new URL(targets.find(t => t.type === "page").url);
const mine = got.cookies.filter(c => pageUrl.hostname.endsWith(c.domain.replace(/^\./, "")));
// Names and lengths only: cookie values are session secrets and stay out of the log.
console.log("cookies for host:", mine.map(c => `${c.name}(len ${c.value.length}, httpOnly=${c.httpOnly}, session=${c.session})`).join(", ") || "none");
const header = mine.map(c => `${c.name}=${c.value}`).join("; ");

async function timed(label, url, headers) {
  const started = Date.now();
  try {
    const r = await fetch(url, { redirect: "manual", headers, signal: AbortSignal.timeout(20000) });
    console.log(label.padEnd(28), "status", r.status, "location", r.headers.get("location"), "ms", Date.now() - started);
  } catch (e) {
    console.log(label.padEnd(28), "FAIL", e.name, e.message, "ms", Date.now() - started);
  }
}
const root = pageUrl.origin + "/";
await timed("no cookies GET /", root, {});
await timed("tab cookies GET /", root, { cookie: header });
await timed("tab cookies GET / (again)", root, { cookie: header });
await timed("tab cookies GET /login", root + "login?returnTo=%2F", { cookie: header });
ws.close();

// Dev-only: open a fresh tab over raw CDP (no Playwright), load a site and log what the page does over time,
// with a main-thread heartbeat. Finds the first thing that goes wrong before a tab becomes unresponsive.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const port = Number(process.argv[2] || 9343);
const siteIndex = Number(process.argv[3] || 2);
const idleSeconds = Number(process.argv[4] || 75);
const closeOld = process.argv.includes("--close-old");
const site = JSON.parse(readFileSync(join(here, "..", "scouting.json"), "utf8")).access[siteIndex];
const t0 = Date.now();
const at = () => ((Date.now() - t0) / 1000).toFixed(1).padStart(6) + "s";
const log = (...a) => console.log(at(), ...a);

if (closeOld) {
  for (const t of await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()) {
    if (t.type === "page") await fetch(`http://127.0.0.1:${port}/json/close/${t.id}`);
  }
}
const target = await (await fetch(`http://127.0.0.1:${port}/json/new?about:blank`, { method: "PUT" })).json();
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map();
let next = 1;
const open = new Map(); // requestId -> label of requests not yet finished
const path = u => { try { const x = new URL(u); return x.pathname + (x.search ? "?…" : ""); } catch { return String(u).slice(0, 60); } };
ws.addEventListener("message", ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
  const p = msg.params || {};
  switch (msg.method) {
    case "Network.requestWillBeSent":
      open.set(p.requestId, `${p.request.method} ${path(p.request.url)} [${p.type}]`);
      log("req ", open.get(p.requestId));
      break;
    case "Network.responseReceived":
      log("resp", p.response.status, path(p.response.url), p.response.mimeType);
      break;
    case "Network.loadingFinished": open.delete(p.requestId); break;
    case "Network.loadingFailed":
      log("FAIL", open.get(p.requestId) || p.requestId, p.errorText, p.canceled ? "(canceled)" : "");
      open.delete(p.requestId);
      break;
    case "Network.eventSourceMessageReceived": log("sse ", p.eventName); break;
    case "Network.webSocketCreated": log("ws  created", path(p.url)); break;
    case "Page.frameStartedNavigating": log("nav  started ->", path(p.url), p.navigationType); break;
    case "Page.frameNavigated": if (!p.frame.parentId) log("nav  committed", path(p.frame.url)); break;
    case "Page.loadEventFired": log("load event"); break;
    case "Page.javascriptDialogOpening": log("DIALOG", p.type, String(p.message).slice(0, 160)); break;
    case "Runtime.consoleAPICalled": log("console", p.type, p.args.map(a => String(a.value ?? a.description ?? "")).join(" ").slice(0, 200)); break;
    case "Log.entryAdded": log("log ", p.entry.level, String(p.entry.text).slice(0, 200)); break;
    case "Inspector.targetCrashed": log("TARGET CRASHED"); break;
  }
});
await new Promise((resolve, reject) => { ws.addEventListener("open", resolve); ws.addEventListener("error", () => reject(new Error("ws error"))); });
function send(method, params = {}, timeoutMs = 8000) {
  const id = next++;
  return new Promise(resolve => {
    const timer = setTimeout(() => { pending.delete(id); resolve({ timeout: true }); }, timeoutMs);
    pending.set(id, msg => { clearTimeout(timer); resolve(msg.error ? { error: msg.error.message } : (msg.result ?? {})); });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
for (const d of ["Page", "Network", "Runtime", "Log"]) await send(d + ".enable");
let alive = true;
async function beat() {
  const r = await send("Runtime.evaluate", { expression: "document.readyState+'|'+location.pathname+'|'+document.title", returnByValue: true }, 2500);
  const ok = !r.timeout && !r.error;
  if (ok !== alive || !ok) log(ok ? "HEARTBEAT back:" : "HEARTBEAT TIMEOUT", ok ? r.result.value : "", "| unfinished requests:", [...open.values()].join("; ") || "none");
  alive = ok;
  return ok ? r.result.value : null;
}
log("navigate", path(site.url));
log("navigate result", JSON.stringify(await send("Page.navigate", { url: site.url }, 20000)).slice(0, 160));
log("state:", await beat());
const until = Date.now() + idleSeconds * 1000;
while (Date.now() < until) { await new Promise(r => setTimeout(r, 3000)); await beat(); }
log("still-open requests after idle:", [...open.values()].join("; ") || "none");
log("second navigate to the same root (the step that hung earlier)");
log("navigate result", JSON.stringify(await send("Page.navigate", { url: site.url }, 20000)).slice(0, 160));
for (let i = 0; i < 6; i++) { await new Promise(r => setTimeout(r, 3000)); log("state:", await beat()); }
ws.close();

// Dev-only: on the tab currently showing a temporary-failure page, follow its retry link repeatedly over raw CDP
// and record what each attempt does: error page again, success, or a request that never gets a response.
const port = Number(process.argv[2] || 9343);
const attempts = Number(process.argv[3] || 10);
const t0 = Date.now();
const at = () => ((Date.now() - t0) / 1000).toFixed(1).padStart(6) + "s";
const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
const page = targets.find(t => t.type === "page");
const ws = new WebSocket(page.webSocketDebuggerUrl);
const pending = new Map();
let next = 1;
const open = new Map();
const seen = [];
const path = u => { try { const x = new URL(u); return x.pathname + (x.search ? "?…" : ""); } catch { return String(u).slice(0, 60); } };
ws.addEventListener("message", ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); return; }
  const p = msg.params || {};
  if (msg.method === "Network.requestWillBeSent" && p.type === "Document") open.set(p.requestId, { url: path(p.request.url), started: Date.now() });
  if (msg.method === "Network.responseReceived" && p.type === "Document") seen.push(`${p.response.status} ${path(p.response.url)} +${Date.now() - (open.get(p.requestId)?.started ?? Date.now())}ms`);
  if (msg.method === "Network.loadingFinished" || msg.method === "Network.loadingFailed") {
    if (msg.method === "Network.loadingFailed" && open.has(p.requestId)) seen.push(`FAILED ${open.get(p.requestId).url} ${p.errorText}`);
    open.delete(p.requestId);
  }
  if (msg.method === "Page.javascriptDialogOpening") seen.push(`DIALOG ${p.type} ${String(p.message).slice(0, 100)}`);
});
