# One number as written: digit groups of three separated by spaces or apostrophes, or digits with dots and commas.
FIRST_NUMBER = re.compile(r"-?(?:\d{1,3}(?:[   ']\d{3})+(?:[.,]\d+)?|\d[\d.,]*\d|\d)")


def number(value, number_format: str | None = None) -> Decimal | None:
    """Parse a number as shown on a page, honouring an explicit locale hint.

    Only the first number in the text is read. A reported value often carries a note with further figures, such
    as "412,750 (en-US = 412750 EUR per 100 ST)"; reading every digit of that as one number gave prices that
    were wrong by many orders of magnitude.
    """
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, Decimal)):
        return Decimal(value)
    if isinstance(value, float):
        return Decimal(str(value))
    text = str(value).strip().replace("−", "-")
    hint = re.search(r"\b([a-z]{2}-[A-Z]{2})\b", text)
    if hint:
        number_format = hint.group(1)
    first = FIRST_NUMBER.search(text)
    if not first:
        return None
    text = re.sub(r"[   ']", "", first.group(0))

