"""Model calls and the agent's log lines of a run on one time axis: python timeline.py <calls.txt> <logs_timed.txt> <from mm:ss> <to mm:ss>"""
import re
import sys

CALL = re.compile(r"\[(\d+):(\d+\.\d+) \+([\d.]+)s(?: wait ([\d.]+)s)?\] \S+ \d+ in ([\d,]+)(?: \(cached ([\d,]+)\))? out ([\d,]+) \$([\d.]+)")
LOG = re.compile(r"\[(\d+):(\d+\.\d+)\] stdout: (.*)")


def seconds(text):
    minutes, rest = text.split(":")
    return int(minutes) * 60 + float(rest)


def clock(value):
    return f"{int(value // 60):02d}:{value % 60:04.1f}"


start, end = seconds(sys.argv[3]), seconds(sys.argv[4])
events = []
for line in open(sys.argv[1], encoding="utf-8"):
    found = CALL.match(line.strip())
    if found:
        began = int(found.group(1)) * 60 + float(found.group(2))
        took = float(found.group(3))
        new, cached, out = (int((found.group(i) or "0").replace(",", "")) for i in (5, 6, 7))
        events.append((began + took, f"    reply  (asked {clock(began)}, {took:5.1f}s)  new {new:6,}  cached {cached:6,}  out {out:5,}  ${float(found.group(8)):.4f}"))
for line in open(sys.argv[2], encoding="utf-8"):
    found = LOG.match(line.strip())
    if found and (" step " in found.group(3) or "recorded" in found.group(3) or "done" in found.group(3) or "error" in found.group(3)
                  or "Investigation" in found.group(3) or "delegated" in found.group(3)):
        events.append((int(found.group(1)) * 60 + float(found.group(2)), found.group(3)[:150]))
for at, text in sorted(events):
    if start <= at <= end:
        print(clock(at), text)

