"""Compact view of a review workflow from its journal: each finding with its skeptic's verdict.

python review_summary.py <journal.jsonl>            overview
python review_summary.py <journal.jsonl> <label>    one agent's full result, e.g. verify:rules:2
"""
import json
import sys

rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
labels = {row["agentId"]: row.get("label") for row in rows if row.get("type") == "started"}
results = {labels.get(row["agentId"], row["agentId"]): row.get("result") for row in rows if row.get("type") == "result"}

if len(sys.argv) > 2:
    print(json.dumps(results.get(sys.argv[2]), ensure_ascii=False, indent=1))
    raise SystemExit

for label in sorted(key for key in results if key and key.startswith("review:")):
    lens = label.split(":", 1)[1]
    report = results[label] or {}
    print("=" * 110)
    print("LENS", lens)
    for number, finding in enumerate(report.get("findings", []), start=1):
        verdict = results.get(f"verify:{lens}:{number}") or {}
        print(f"\n[{number}] {finding['title']}")
        print("    where:", (finding.get("where") or "")[:240])
        print("    rated:", finding.get("certainty", finding.get("severity", "")), "| damage:", (finding.get("damage") or "")[:380])
        if verdict:
            print("    VERDICT holds:", verdict.get("holds"), "| patch ok:", verdict.get("patch_ok", verdict.get("fix_ok")))
            print("    result:", (verdict.get("result") or "")[:500])
            print("    corrections:", (verdict.get("corrections") or verdict.get("better_fix") or "")[:800])
        else:
            print("    (no verdict)")
    fine = report.get("checked_and_fine") or report.get("fine") or []
    print(f"\n    checked and fine: {len(fine)} items")

