async def dismiss_blocking_dialogs(self, site: str, control=None) -> list[str]:
    """Close open modal popups through their own close button (never their accept/navigate links).

    A popup that holds `control`, the control about to be used, stays open, and so does one that asks for
    input (a search help, a code prompt): those are part of the task, not overlays."""
    close = """node => {
        const names = /^(×|x|✕|schließen|schliessen|close|ausblenden|später|later|abbrechen)$/i;
        const out = [];
        // the control's document, then the document of each frame that holds it
        for (let n = node; n; n = n.ownerDocument && n.ownerDocument.defaultView.frameElement) {
            for (const d of (n.ownerDocument || n).querySelectorAll('dialog[open],[role=dialog],[aria-modal=true]')) {
                if (!(d.offsetWidth || d.offsetHeight) || d.contains(n)) continue;
                if (d.querySelector('select,textarea,input:not([type=hidden]):not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit])')) continue;
                const button = [...d.querySelectorAll('button,[role=button]')].find(b =>
                    names.test((b.getAttribute('aria-label') || '').trim())
                    || names.test((b.innerText || '').trim()));
                if (button) { button.click(); out.push(d.getAttribute('aria-label') || d.id || 'dialog'); }
            }
        }
        return out;
    }"""
    closed = []
    if control is not None:
        try:
            closed.extend(await asyncio.wait_for(control.evaluate(close), 3))
        except Exception:
            pass
    else:
        for frame in self._page(site).frames:
            try:
                closed += await asyncio.wait_for(frame.evaluate(f"({close})(document)"), 3)
            except Exception:
                pass
    if closed:
        await self._page(site).wait_for_timeout(150)
    return closed

