import json
import sys

rows = [json.loads(line) for line in open(sys.argv[1], encoding="utf-8") if line.strip()]
width = int(sys.argv[2]) if len(sys.argv) > 2 else 330
labels = {row["agentId"]: row.get("label") for row in rows if row.get("type") == "started"}
for row in rows:
    label = labels.get(row.get("agentId"))
    if row.get("type") != "result" or not label or not label.startswith("check:"):
        continue
    print("=" * 100)
