    for verdict in row["result"].get("verdicts", []):
        print(f"\n  {verdict['name'][:70]}\n    holds: {verdict['holds']} | {verdict['corrected_figure'][:width]}\n    note: {verdict['note'][:width]}")
    for item in row["result"].get("missed", []):
        print("\n  MISSED:", item[:width + 200])

