"""Turn the saved platform records of every run into one data file and a text report.

python build_data.py <folder of run folders> [--out data.js] [--notes notes.json] [--text [run id ...]]

Each run folder holds get_run.txt, calls.txt, logs.txt, inputs.txt and, for failed runs, diagnose.txt.
The agent logs come from four code lines with four formats; all are reduced to the same events:
(time on the run's clock, worker, kind, action, page, ok, text).
"""
import json
import re
import statistics
import sys
from collections import Counter, defaultdict
from pathlib import Path

MAX = {"decision": 5, "tender_reference": 5, "discount_percent": 5, "total_net": 5, "total_consistency": 5,
       "withdrawn_answer": 5, "index_window": 5, "material_number": 2.6, "quantity": 1.95, "base_unit_price": 1.95,
       "surcharge_per_unit": 1.3, "packaging_per_unit": 1.3, "rebate_total": 1.3, "unit_price": 1.3, "lead_time_weeks": 1.3}
POSITIONS = ["01.01", "01.02", "01.03", "01.04", "01.05"]
LINES = {"A": "rfq_agent (plan, investigators, pricing, submit worker; Qwen only)",
         "B": "agents/web/submit (master and site workers, form prepared in parallel; Qwen and Clef)",
         "C": "master/worker/factboard, first version (Qwen and Clef)",
         "D": "master/worker/factboard, grown version (Qwen and Clef)",
         "E": "single-file agent (early)", "F": "reasoning/web_tools (Qwen only)"}
STAMP = re.compile(r"^\[([\d:]+\.\d+)\] stdout: ?(.*)$")
CALL = re.compile(r"\[([\d:]+\.\d+) \+([\d.]+)s(?: wait ([\d.]+)s)?\] (\S+) (\d+) in ([\d,]+)(?: \(cached ([\d,]+)\))? out ([\d,]+) \$([\d.]+)")
INPUT = re.compile(r"^\[([\d:]+\.\d+)\] browser (\d+): (\w+)")
KV = re.compile(r"(?:^| )([a-z_]+)=")


def secs(text):
    """'06:14', '1:06:04', '12:03.5', '108s' or '0.4s' as seconds."""
    text = text.strip()
    if text.endswith("s") and ":" not in text:
        return float(text[:-1])
    value = 0.0
    for part in text.split(":"):
        value = value * 60 + float(part)
    return value


def number(text):
    return int(text.replace(",", ""))


def short(text, width=150):
    text = re.sub(r"\s+", " ", str(text)).strip()
    return text if len(text) <= width else text[:width - 1] + "…"


def page_of(url):
    """A page name without scheme and host: the path and its query."""
    found = re.match(r"https?://([^/\s]+)(/\S*)?", url)
    if found:
        url = found.group(2) or "/"
    return url[:110]


def pairs(text):
    out, marks = {}, list(KV.finditer(text))
    for index, mark in enumerate(marks):
        end = marks[index + 1].start() if index + 1 < len(marks) else len(text)
        out[mark.group(1)] = text[mark.end():end].strip()
    return out


# ---------------------------------------------------------------- the platform's summary of a run

def summary_of(text):
    lines = text.splitlines()
    head = re.match(r"(run_\w+) · (\w+) run.*?package (\w+) \((\d+) files\)", lines[0])
    run = {"id": head.group(1), "kind": head.group(2), "package": head.group(3), "files": int(head.group(4)),
           "status": "", "failure": "", "quality": None, "eligible": False, "cost": 0.0, "seconds": 0.0, "costTime": None,
           "start": "", "llm": {"models": []}, "fields": [], "answer": None}
    points = False
    for line in lines[1:]:
        if line.startswith("Status"):
            found = re.match(r"Status (\w+), phase (\w+)(?: · Failure: (.*))?", line)
            run["status"], run["failure"] = found.group(1), found.group(3) or ""
        elif line.startswith("Started"):
            found = re.match(r"Started (.*?) UTC(?: · finished .*? UTC)? · ran ([\d:]+)", line)
            if found:
                run["start"], run["seconds"] = found.group(1), secs(found.group(2))
        elif line.startswith("LLM:"):
            found = re.match(r"LLM: (\d+) calls?, \$([\d.]+), ([\d,]+) in / ([\d,]+) out tokens, (\S+) in calls \(p50 ([\d.]+)s, p95 ([\d.]+)s\), at most (\d+)", line)
            if found:
                run["llm"].update(calls=int(found.group(1)), cost=float(found.group(2)), tokensIn=number(found.group(3)),
                                  tokensOut=number(found.group(4)), inCalls=secs(found.group(5)), p50=float(found.group(6)),
                                  p95=float(found.group(7)), atOnce=int(found.group(8)))
        elif re.match(r"\s+\S+/\S+: \d+ calls?", line):
            found = re.match(r"\s+(\S+): (\d+) calls?(?: \((\d+) failed\))?, \$([\d.]+), ([\d,]+) in(?: \(([\d,]+) cached\))? / ([\d,]+) out, (\S+) in calls", line)
            if found:
                run["llm"]["models"].append({"name": found.group(1), "calls": int(found.group(2)), "failed": int(found.group(3) or 0),
                                             "cost": float(found.group(4)), "new": number(found.group(5)), "cached": number(found.group(6) or "0"),
                                             "out": number(found.group(7)), "inCalls": secs(found.group(8))})
        elif line.startswith("Score:"):
            found = re.match(r"Score: quality ([\d.]+), (eligible|not eligible), cost \$([\d.]+), time ([\d:]+)(?:, cost × time ([\d.,]+))?", line)
            if found:
                run["quality"], run["eligible"] = float(found.group(1)), found.group(2) == "eligible"
                run["cost"] = float(found.group(3))
                run["costTime"] = float(found.group(5).replace(",", "")) if found.group(5) else None
        elif line.startswith("Points per field"):
            points = True
        elif points and line.startswith("  "):
            found = re.match(r"\s+([\w\[\]\.]+): ([\d.]+)(?: \(entered (.*)\))?$", line)
            if found and found.group(1) not in ("extra_positions", "position_points"):
                run["fields"].append([found.group(1), float(found.group(2)), found.group(3) or ""])
        elif line.startswith('{"tender_reference"'):
            points = False
            try:
                run["answer"] = json.loads(line)
            except ValueError:
                run["answer"] = {"cut": line[:300]}
        elif not line.startswith(" "):
            points = False
    if not run["cost"]:
        run["cost"] = run["llm"].get("cost", 0.0)
    return run


def score_of(run):
    """Points lost, by position and by kind of field; None where the run has no score."""
    if run["quality"] is None or not run["fields"]:
        return None
    got = {name: value for name, value, _ in run["fields"]}
    entered = {name: text for name, _, text in run["fields"]}
    lost, positions = [], {}
    for name in ("decision", "tender_reference", "discount_percent", "total_net", "total_consistency", "withdrawn_answer", "index_window"):
        missing = round(MAX[name] - got.get(name, 0), 2)
        if missing > 0:
            lost.append([name, missing, entered.get(name, "")])
    for position in POSITIONS:
        whole = got.get(f"positions[{position}]", 0)
        fields = {}
        for field in ("material_number", "quantity", "base_unit_price", "surcharge_per_unit", "packaging_per_unit", "rebate_total", "unit_price", "lead_time_weeks"):
            key = f"positions[{position}].{field}"
            fields[field] = [got.get(key, 0), MAX[field], entered.get(key, "")]
        is_entered = any(text not in ("", "null") for _, _, text in fields.values())
        positions[position] = {"got": round(whole, 2), "entered": is_entered, "fields": fields}
        if not is_entered:
            lost.append([f"{position} not entered", round(13 - whole, 2), ""])
        else:
            for field, (value, most, text) in fields.items():
                if most - value > 0.001:
                    lost.append([f"{position} {field}", round(most - value, 2), text])
    return {"lost": lost, "positions": positions}


# ---------------------------------------------------------------- the agent's log, four formats

def detect(lines, files):
    sample = "\n".join(text for _, text in lines[:200])
    if '{"timestamp"' in sample:
        return "C"
    if re.search(r"^\[ *[\d.]+s\] \w+ left=", sample, re.M):
        return "D"
    if re.search(r"^ *[\d.]+s \[[\w-]+\] ", sample, re.M):
        return "B"
    if re.search(r"\] step \d+: ", sample) or files == 18:
        return "A"
    return {8: "E", 10: "F", 12: "B", 13: "B", 17: "C", 19: "D"}.get(files, "?")


def event(at, worker, kind, action="", page="", ok=True, text="", took=0.0):
    return {"t": round(at, 1), "w": worker or "", "k": kind, "a": action, "p": page, "ok": ok, "x": short(text), "d": took}


A_STEP = re.compile(r"^\[([\w-]+)\] step (\d+): (\w+)(?: \[([\w-]+)\])?")
A_WORKER = re.compile(r"^\[([\w-]+)\] (.*)$")
A_MARK = re.compile(r"^(Assignment \[|Investigation finished|Calculated bid|Remaining gaps|Stopping \d+|Bid sheet published|Planning|"
                    r"Portal submission|Submission|No confirmed|Signed|Traceback|second round|Plan:|Round \d|Phase \d|Decision)")


def format_a(lines):
    events, last_tool = [], {}
    for at, text in lines:
        step = A_STEP.match(text)
        if step:
            worker, number_, tool, site = step.groups()
            last_tool[worker] = tool
            events.append(event(at, worker, "step", tool, "", True, f"step {number_}" + (f" on {site}" if site else "")))
            events.append(event(at, worker, "model", "qwen", "", True, f"step {number_}"))
            continue
        found = A_WORKER.match(text)
        if found:
            worker, rest = found.groups()
            if rest.startswith("tool error:"):
                kind = re.search(r'"error": "(\w+)", "message": "(.{0,140})', rest)
                title = re.search(r'"title": "(.{0,60}?)"', rest)
                url = re.search(r'"url": "([^"]{0,140})', rest)
                where = page_of(url.group(1)) if url else ""
                events.append(event(at, worker, "error", last_tool.get(worker, ""), where, False,
                                    (kind.group(1) + ": " + kind.group(2)) if kind else rest[11:]) | {"title": title.group(1) if title else ""})
            elif "stopped at step" in rest:
                events.append(event(at, worker, "error", "form_sequence", "", False, rest))
            elif rest.startswith("recorded "):
                events.append(event(at, worker, "record", rest.split(":")[0][9:], "", True, rest[9:]))
            elif rest.startswith(("refused ", "rejected ")):
                events.append(event(at, worker, "refused", rest.split(":")[0].split(" ", 1)[1], "", False, rest))
            elif rest.startswith("model unavailable"):
                events.append(event(at, worker, "error", "model", "", False, rest))
            elif rest.startswith("deadline reached"):
                events.append(event(at, worker, "stop", "", "", True, rest))
            else:
                events.append(event(at, worker, "note", "", "", True, rest))
            continue
        if text.startswith("Model call failed"):
            events.append(event(at, "", "retry", "qwen", "", False, text))
        elif A_MARK.match(text):
            events.append(event(at, "", "mark", "", "", True, text))
    return events


B_LINE = re.compile(r"^ *([\d.]+)s \[([\w-]+)\] (.*)$")


def format_b(lines):
    events, page = [], {}
    for at, text in lines:
        found = B_LINE.match(text)
        if not found:
            continue
        worker, rest = found.group(2), found.group(3)
        label, _, body = rest.partition(": ")
        if worker == "master":
            events.append(event(at, worker, "mark", "", "", True, rest))
            continue
        if rest.startswith("stopped after"):
            events.append(event(at, worker, "stop", "", page.get(worker, ""), True, rest))
            continue
        if "records; next:" in rest:
            events.append(event(at, worker, "model", "qwen", page.get(worker, ""), True, rest))
            continue
        if label in ("note", "rejected") or not body:
            kind = "refused" if label == "rejected" else "error" if "not readable" in rest or "failed" in rest else "note"
            if worker == "submit" and kind == "note" and re.match(r"(filled|clicked|selected|checked|set|pressed|opened)", rest):
                kind = "step"
            events.append(event(at, worker, kind, rest.split(" ")[0] if kind == "step" else "", page.get(worker, ""), kind in ("note", "step"), rest))
            continue
        target = re.search(r"→(/\S*)", body) or re.search(r"opened (https?://\S+)", body) or re.search(r"read \d+ pages?: (\S+)", body)
        if target:
            page[worker] = page_of(target.group(1))
        action = body.split(" ")[0]
        failed = "(disabled)" in body or "not found" in body or "failed" in body
        events.append(event(at, worker, "step", f"{label}:{action}", page.get(worker, ""), not failed, body))
    return events


def format_c(lines):
    events = []
    for at, text in lines:
        if not text.startswith("{"):
            continue
        try:
            row = json.loads(text)
        except ValueError:
            continue
        worker, phase, action = row.get("worker", ""), row.get("phase", ""), row.get("action", "")
        if phase == "model":
            if action == "call":
                events.append(event(at, worker, "model", row.get("model", ""), "", True, f"attempt {row.get('attempt')}", float(row.get("seconds") or 0)))
            elif action == "retry":
                events.append(event(at, worker, "retry", row.get("model", ""), "", False, f"{row.get('error_type')} after {row.get('seconds')}s {row.get('error', '')}"))
        elif phase == "browser":
            detail = row.get("reason") or row.get("target") or ""
            events.append(event(at, worker, "step", action, "", True, f"step {row.get('step')} {detail}"))
        elif phase == "gate":
            verdict = row.get("clef_verdict", {})
            if verdict.get("obstacle") not in (None, "none"):
                events.append(event(at, worker, "note", "obstacle", "", True, f"step {row.get('step')}: obstacle {verdict.get('obstacle')}, page kind {verdict.get('page_kind')}, recovery {verdict.get('recovery')}"))
        elif action == "tool_error":
            events.append(event(at, worker, "error", row.get("tool") or row.get("action_name") or "", "", False, row.get("error", "")))
        elif action == "stopped":
            events.append(event(at, worker, "stop", "", "", True, f"{row.get('reason')} after {row.get('steps')} steps"))
        elif action == "fact_posted":
            events.append(event(at, worker, "record", "fact", "", True, f"{row.get('facts_posted')} for {row.get('goal')}"))
        else:
            rest = {key: value for key, value in row.items() if key not in ("timestamp", "elapsed", "remaining", "phase", "worker", "action")}
            kind = "mark" if phase in ("synthesis", "submission", "master", "plan", "run") or worker in ("master", "submitter") else "note"
            events.append(event(at, worker, kind, f"{phase}:{action}", "", "fail" not in action and "error" not in action, f"{phase} {action} {json.dumps(rest, ensure_ascii=False) if rest else ''}"))
    return events


D_LINE = re.compile(r"^\[ *([\d.]+)s\] (\w+) (.*)$")


def format_d(lines):
    events, page, extra = [], {}, {}
    parsed = []
    for at, text in lines:
        found = D_LINE.match(text)
        if found:
            parsed.append((at, float(found.group(1)), found.group(2), pairs(found.group(3)), found.group(3)))
    for index, (at, clock, kind, row, raw) in enumerate(parsed):
        worker = row.get("worker", "")
        if kind == "gate":
            page[worker] = page_of(row.get("url", ""))
            events.append(event(at, worker, "page", "", page[worker], True, f"step {row.get('step')} {row.get('gate', '')}"))
        elif kind in ("tool", "submit_tool", "form_tool", "recover_tool"):
            ok = row.get("ok", "true") == "true"
            detail = " ".join(part for part in (row.get("args", ""), row.get("result", ""), row.get("text", "")) if part)
            name = row.get("tool", "") if kind != "recover_tool" else "recover:" + row.get("tool", "")
            events.append(event(at, worker, "step" if ok else "error", name, page.get(worker, ""), ok, detail))
        elif kind == "qwen":
            label = row.get("label", "")
            who = label.split("#")[0]
            who = "submitter" if row.get("role") == "submit" else ("w:" + who if row.get("role") == "worker" else row.get("role", who))
            events.append(event(at, who, "model", "qwen", "", True, f"{label} out {row.get('tokens_out')} reasoning {row.get('reasoning')} retries {row.get('retries')} {row.get('tools', '')}",
                                float(row.get("latency") or 0)))
        elif kind == "clef":
            who = ""
            for later in parsed[index + 1:index + 3]:
                if later[2] == "gate" and later[1] - clock <= 0.3:
                    who = later[3].get("worker", "")
            events.append(event(at, who, "model", "clef", "", True, row.get("label", ""), float(row.get("latency") or 0)))
        elif kind in ("qwen_retry", "clef_retry", "structured_retry"):
            events.append(event(at, "submitter" if row.get("role") == "submit" else row.get("role", ""), "retry", kind.split("_")[0], "", False, raw))
        elif kind == "board":
            happening = row.get("ev", "")
            if happening in ("phase", "submission"):
                events.append(event(at, "", "mark", happening, "", row.get("phase") != "failed", f"{happening}: {row.get('phase')} {row.get('note', '')}"))
            elif happening == "worker":
                events.append(event(at, row.get("worker_id", ""), "stop", "", "", True, f"{row.get('status')}: {row.get('stop_reason', '')} after {row.get('steps', '?')} steps"))
            else:
                events.append(event(at, row.get("by", ""), "note", happening, "", True, raw))
        elif kind == "worker_stop":
            events.append(event(at, worker, "stop", "", page_of(row.get("page", "")), True, f"{row.get('reason')} after {row.get('steps')} steps"))
        elif kind in ("obstacle", "submit_obstacle"):
            events.append(event(at, worker, "note", "obstacle", page.get(worker, ""), row.get("handled") == "true",
                                f"obstacle {row.get('obstacle')} handled={row.get('handled')} {row.get('note', '')}"))
        elif kind in ("fact", "extracted", "lookup_found"):
            events.append(event(at, worker, "record", kind, "", True, row.get("fact") or raw))
        elif kind in ("delivery_error", "merge_failed", "recover_give_up", "submit_blocked", "watchdog"):
            events.append(event(at, worker, "error", kind, "", False, raw))
        elif kind in ("summary", "delivery_result"):
            events.append(event(at, "", "mark", kind, "", True, raw))
            extra[kind] = raw
        else:
            events.append(event(at, worker, "mark" if not worker else "note", kind, "", True, f"{kind} {raw}"))
    return events, extra


def plain(lines):
    return [event(at, "", "mark" if re.match(r"(Phase|Traceback|Error|Round|Plan|Submitting|Deadline|No )", text) else "note", "", "", True, text)
            for at, text in lines if text.strip()]


# ---------------------------------------------------------------- one run

def build(folder):
    def read(name):
        path = folder / name
        return path.read_text(encoding="utf-8", errors="replace") if path.exists() else ""

    run = summary_of(read("get_run.txt"))
    run["score"] = score_of(run)
    end = run["seconds"]

    calls = []
    for line in read("calls.txt").splitlines():
        found = CALL.match(line.strip())
        if found:
            start, took = secs(found.group(1)), float(found.group(2))
            calls.append({"start": start, "took": took, "end": start + took, "model": found.group(4).split("/")[0], "status": int(found.group(5)),
                          "new": number(found.group(6)), "cached": number(found.group(7) or "0"), "out": number(found.group(8)),
                          "cost": float(found.group(9)), "worker": ""})
    calls.sort(key=lambda call: call["start"])

    lines = []
    for line in read("logs.txt").splitlines():
        found = STAMP.match(line)
        if found:
            lines.append((secs(found.group(1)), found.group(2)))
    kind = detect(lines, run["files"])
    run["line"], run["lineName"] = kind, LINES.get(kind, "")
    extra = {}
    if kind == "A":
        events = format_a(lines)
    elif kind == "B":
        events = format_b(lines)
    elif kind == "C":
        events = format_c(lines)
    elif kind == "D":
        events, extra = format_d(lines)
    else:
        events = plain(lines)
    run["log"] = {"from": lines[0][0] if lines else None, "to": lines[-1][0] if lines else None, "lines": len(lines)}

    # Each model answer the log names goes to the nearest unclaimed call of that model ending at that moment.
    free = {id(call): call for call in calls}
    for item in [e for e in events if e["k"] == "model" and e["w"]]:
        best, distance = None, 1.6
        for call in free.values():
            if call["model"] == item["a"] and abs(call["end"] - item["t"]) < distance:
                best, distance = call, abs(call["end"] - item["t"])
        if best:
            best["worker"] = item["w"]
            item["cost"], item["d"], item["out"] = best["cost"], best["took"], best["out"]
            del free[id(best)]

    # Milestones: the end of gathering, the moment the bid was decided, the first action of the submitter after it.
    marks = [(e["t"], e["x"]) for e in events if e["k"] == "mark"]
    gather_end = bid_ready = None
    if kind == "A":
        gather_end = next((at for at, text in marks if text.startswith("Investigation finished")), None)
        bid_ready = next((at for at, text in marks if text.startswith(("Bid sheet published", "Calculated bid"))), None)
    elif kind == "B":
        gather_end = next((at for at, text in marks if "research finished" in text), None)
        bid_ready = next((at for at, text in marks if text.startswith("bid:")), None)
    elif kind == "C":
        gather_end = next((e["t"] for e in events if e["a"] == "synthesis:started"), None)
        bid_ready = next((e["t"] for e in events if e["a"].startswith("submission:")), None)
    elif kind == "D":
        phases = re.search(r"phases=(\{[^}]*)", extra.get("summary", ""))
        found = dict(re.findall(r'"(\w+)": ([\d.]+)', phases.group(1))) if phases else {}
        offset = statistics.median([at - float(D_LINE.match(text).group(1)) for at, text in lines if D_LINE.match(text)] or [0.9])
        gather_end = float(found["merging"]) + offset if "merging" in found else next((at for at, text in marks if "phase: merging" in text), None)
        bid_ready = float(found["delivery"]) + offset if "delivery" in found else next((at for at, text in marks if "phase: delivery" in text), None)
        run["agentSummary"] = short(extra.get("summary", ""), 900)
    submit_names = {e["w"] for e in events if "submit" in e["w"]}
    confirmed = run["answer"] is not None
    run["phase"] = {"gatherEnd": gather_end, "bidReady": bid_ready, "end": end}

    def spend(start, stop):
        inside = [call for call in calls if start <= call["end"] < stop]
        return {"calls": len(inside), "cost": round(sum(call["cost"] for call in inside), 4), "seconds": round(stop - start, 1),
                "out": sum(call["out"] for call in inside)}

    if gather_end is not None:
        split = {"gathering": spend(0, gather_end)}
        if bid_ready is not None and bid_ready >= gather_end:
            split["deciding"] = spend(gather_end, bid_ready)
            split["submitting"] = spend(bid_ready, end + 60)
            split["submitting"]["seconds"] = round(end - bid_ready, 1)
        else:
            split["after gathering"] = spend(gather_end, end + 60)
            split["after gathering"]["seconds"] = round(end - gather_end, 1)
        run["split"] = split

    # Per worker: what it did in the kept log, where it sat, when it was quiet.
    workers = defaultdict(list)
    for item in events:
        if item["w"]:
            workers[item["w"]].append(item)
    stats = []
    for name, rows in workers.items():
        acts = [e for e in rows if e["k"] in ("step", "error")]
        if not acts and not any(e["k"] == "model" for e in rows):
            continue
        mine = [call for call in calls if call["worker"] == name]
        times = [e["t"] for e in rows if e["k"] in ("step", "error", "model", "page")]
        quiet = []
        ordered = [e for e in rows if e["k"] in ("step", "error", "model", "page", "stop")]
        for before, after in zip(ordered, ordered[1:]):
            if after["t"] - before["t"] >= 30 and before["k"] != "stop":
                quiet.append([before["t"], round(after["t"] - before["t"], 1), short(f"{before['a']} {before['x']}", 90)])
        # Stays on one page (where the log names pages) and runs of one repeated action.
        stays, current = [], None
        for e in rows:
            if e["k"] not in ("step", "error", "page") or not e["p"]:
                continue
            if current and current[0] == e["p"]:
                current[2], current[3] = e["t"], current[3] + (e["k"] != "page")
            else:
                current = [e["p"], e["t"], e["t"], int(e["k"] != "page")]
                stays.append(current)
        for stay, following in zip(stays, stays[1:]):
            stay[2] = following[1]
        stays = sorted(([p, a, round(b - a, 1), n] for p, a, b, n in stays if b - a >= 40 or n >= 6), key=lambda stay: -stay[2])[:6]
        repeats, current = [], None
        for e in acts:
            signature = (e["a"], re.sub(r"step \d+ ?", "", e["x"])[:70] if kind in ("B", "D") else "")
            if current and current[0] == signature:
                current[2], current[3], current[4] = e["t"], current[3] + 1, current[4] + (not e["ok"])
            else:
                current = [signature, e["t"], e["t"], 1, int(not e["ok"])]
                repeats.append(current)
        repeats = sorted(([" ".join(part for part in s if part), a, round(b - a, 1), n, bad] for s, a, b, n, bad in repeats if n >= 4),
                         key=lambda item: -item[3])[:6]
        stop = next((e["x"] for e in reversed(rows) if e["k"] == "stop"), "")
        stats.append({"name": name, "submit": "submit" in name, "first": min(times) if times else None, "last": max(times) if times else None,
                      "steps": len(acts), "errors": sum(1 for e in acts if not e["ok"]), "refused": sum(1 for e in rows if e["k"] == "refused"),
                      "records": sum(1 for e in rows if e["k"] == "record"),
                      "modelCalls": len(mine) or sum(1 for e in rows if e["k"] == "model"), "cost": round(sum(call["cost"] for call in mine), 4),
                      "inCalls": round(sum(call["took"] for call in mine), 1), "out": sum(call["out"] for call in mine),
                      "tools": Counter(e["a"] for e in acts).most_common(8), "stop": stop, "quiet": sorted(quiet, key=lambda q: -q[1])[:5],
                      "stays": stays, "repeats": repeats})
    stats.sort(key=lambda worker: (worker["submit"], worker["first"] or 0))
    run["workers"] = stats

    grouped = defaultdict(list)
    for item in events:
        if item["k"] in ("error", "refused"):
            message = re.sub(r"\d+", "N", item["x"])[:95]
            grouped[(item["w"], item["a"], message)].append(item)
    run["errors"] = sorted(([w, a, m, len(rows), rows[0]["t"], rows[-1]["t"], rows[-1]["p"] or rows[-1].get("title", "")] for (w, a, m), rows in grouped.items()),
                           key=lambda row: -row[3])[:14]
    retries = Counter(re.sub(r".*?(\w+Error).*", r"\1", e["x"]) for e in events if e["k"] == "retry")
    run["retries"] = retries.most_common(5)

    # Whole-run measures from the call list: time with no call in flight, slow calls, calls that failed.
    idle, busy_until = [], 0.0
    for call in calls:
        if call["start"] - busy_until >= 15:
            before = next((text for at, text in reversed(lines) if at <= busy_until + 0.5), "") if lines and lines[0][0] <= busy_until else ""
            idle.append([round(busy_until, 1), round(call["start"] - busy_until, 1), short(before, 110)])
        busy_until = max(busy_until, call["end"])
    if calls and end - busy_until >= 15:
        idle.append([round(busy_until, 1), round(end - busy_until, 1), "until the run ended"])
    run["idle"] = sorted(idle, key=lambda row: -row[1])[:10]
    run["slow"] = [[round(c["start"], 1), round(c["took"], 1), c["out"], c["model"], c["worker"]] for c in sorted(calls, key=lambda c: -c["took"])[:8] if c["took"] >= 30]
    run["failedCalls"] = Counter(str(c["status"]) for c in calls if c["status"] != 200).most_common(4)
    tokens = {"new": sum(c["new"] for c in calls), "cached": sum(c["cached"] for c in calls), "out": sum(c["out"] for c in calls)}
    run["tokens"] = tokens
    run["longAnswers"] = {"over1000": sum(1 for c in calls if c["out"] >= 1000), "seconds": round(sum(c["took"] for c in calls if c["out"] >= 1000), 1),
                          "cost": round(sum(c["cost"] for c in calls if c["out"] >= 1000), 4)}
    run["inCalls"] = round(sum(c["took"] for c in calls), 1)

    # Browser inputs, whole run: activity per browser and its long silences while the run was going.
    inputs = defaultdict(list)
    for line in read("inputs.txt").splitlines():
        found = INPUT.match(line)
        if found:
            inputs[int(found.group(2))].append((secs(found.group(1)), found.group(3)[0]))
    browsers = {}
    for browser, rows in sorted(inputs.items()):
        times = [at for at, _ in rows]
        gaps = [[round(a, 1), round(b - a, 1)] for a, b in zip([0.0] + times, times + [end]) if b - a >= 60]
        # Which worker drove it: the worker whose logged actions fall on its inputs most often.
        votes = Counter()
        for at in times:
            for item in events:
                if item["k"] in ("step", "error") and item["w"] and abs(item["t"] - at) <= 0.8:
                    votes[re.sub(r"^w\d+-|^w:", "", item["w"])] += 1
        owner = votes.most_common(1)[0][0] if votes and votes.most_common(1)[0][1] >= 3 else ""
        browsers[browser] = {"n": len(rows), "owner": owner, "times": [round(at, 1) for at in times], "quiet": sorted(gaps, key=lambda g: -g[1])[:5]}
    run["browsers"] = browsers

    # The submitter after the bid was decided.
    if submit_names:
        mine = [e for e in events if e["w"] in submit_names and e["k"] in ("step", "error", "model", "note", "mark")]
        after = [e for e in mine if bid_ready is None or e["t"] >= bid_ready - 0.5]
        acts = [e for e in after if e["k"] in ("step", "error")]
        code = [e for e in events if re.search(r"TAN|signing|Signatur|code", e["x"] + e["a"], re.I) and (bid_ready is None or e["t"] >= bid_ready - 0.5)]
        run["submission"] = {"firstPrepared": min((e["t"] for e in mine), default=None), "from": bid_ready, "steps": len(acts),
                             "errors": sum(1 for e in acts if not e["ok"]), "modelCalls": sum(1 for e in after if e["k"] == "model"),
                             "firstCode": code[0]["t"] if code else None, "codeLines": len(code), "confirmed": confirmed,
                             "last": [[e["t"], e["k"], e["a"], e["x"]] for e in after if e["k"] != "model"][-10:]}
    run["calls"] = [[round(c["start"], 1), round(c["took"], 1), c["model"], c["new"], c["cached"], c["out"], c["cost"], c["status"], c["worker"]] for c in calls]
    run["events"] = [[e["t"], e["w"], e["k"], e["a"], e["p"], 1 if e["ok"] else 0, e["x"]] for e in events
                     if not (e["k"] == "model" and kind in ("A", "B")) and e["k"] != "page"]
    diagnosis = read("diagnose.txt").splitlines()
    run["diagnosis"] = [short(line, 260) for line in diagnosis[:6] if line.strip()]
    return run


# ---------------------------------------------------------------- text report

def clock(value):
    return "--:--" if value is None else f"{int(value // 60):02d}:{int(value % 60):02d}"


def report(run):
    quality = "no score" if run["quality"] is None else f"quality {run['quality']:g}{'' if run['eligible'] else ' (not eligible)'}"
    print("=" * 112)
    print(f"{run['id']}  line {run['line']} ({run['files']} files, {run['package']})  {run['status']}  {quality}  ${run['cost']:.4f}  {clock(run['seconds'])}  "
          f"started {run['start']}")
    if run["failure"]:
        print("  failure:", run["failure"])
    models = "; ".join(f"{m['name'].split('/')[1]} {m['calls']} calls ${m['cost']:.4f} out {m['out']:,} in-calls {m['inCalls']:.0f}s" for m in run["llm"]["models"])
    print(f"  models: {models}")
    print(f"  tokens new {run['tokens']['new']:,} cached {run['tokens']['cached']:,} out {run['tokens']['out']:,}; answers of 1,000+ tokens: {run['longAnswers']['over1000']} "
          f"({run['longAnswers']['seconds']:.0f}s, ${run['longAnswers']['cost']:.3f}); retries {run['retries']}; failed calls {run['failedCalls']}")
    if run["score"]:
        print("  lost:", "; ".join(f"{name} -{points:g}{' (entered ' + text + ')' if text else ''}" for name, points, text in run["score"]["lost"]) or "nothing")
    phase = run["phase"]
    print(f"  log kept {clock(run['log']['from'])}-{clock(run['log']['to'])} ({run['log']['lines']} lines); gathering ended {clock(phase['gatherEnd'])}, bid decided {clock(phase['bidReady'])}, "
          f"run ended {clock(phase['end'])}")
    for name, part in run.get("split", {}).items():
        print(f"    {name:16s} {part['seconds']:6.0f}s  {part['calls']:3d} calls  ${part['cost']:.4f}  out {part['out']:,}")
    for worker in run["workers"]:
        print(f"  {worker['name']:20s} {clock(worker['first'])}-{clock(worker['last'])} steps {worker['steps']:3d} (failed {worker['errors']}, refused {worker['refused']}) "
              f"calls {worker['modelCalls']:3d} ${worker['cost']:.3f} {worker['inCalls']:.0f}s | {dict(worker['tools'][:6])} | {worker['stop'][:60]}")
        for at, took, before in worker["quiet"][:3]:
            print(f"      quiet {took:.0f}s from {clock(at)} after: {before}")
        for page, at, took, steps in worker["stays"][:4]:
            print(f"      on one page {took:.0f}s from {clock(at)}, {steps} actions: {page}")
        for what, at, took, count, bad in worker["repeats"][:4]:
            print(f"      same action {count}x ({bad} failed) over {took:.0f}s from {clock(at)}: {what}")
    for worker, action, message, count, first, last, where in run["errors"][:9]:
        print(f"  error {count}x {worker} {action}: {message} | {clock(first)}-{clock(last)} | {where[:60]}")
    if run["idle"]:
        print("  no call in flight:", ", ".join(f"{took:.0f}s from {clock(at)}" for at, took, _ in run["idle"][:7]))
    if run["slow"]:
        print("  slowest calls:", ", ".join(f"{clock(at)} {took:.0f}s out {out} {worker}" for at, took, out, _, worker in run["slow"][:7]))
    print("  browsers:", "; ".join(f"b{number_} {b['owner'] or '?'} {b['n']} inputs, longest silences {[f'{clock(a)}+{d:.0f}s' for a, d in b['quiet'][:3]]}" for number_, b in run["browsers"].items()))
    submission = run.get("submission")
    if submission:
        print(f"  submitter: first seen {clock(submission['firstPrepared'])}, after the bid {submission['steps']} actions ({submission['errors']} failed), "
              f"{submission['modelCalls']} model answers, first signing line {clock(submission['firstCode'])}, answer entered: {submission['confirmed']}")
        for at, kind, action, text in submission["last"][-7:]:
            print(f"      {clock(at)} {kind:5s} {action} {text[:150]}")
    for line in run["diagnosis"][:3]:
        print("  platform:", line[:200])
    if run.get("agentSummary"):
        print("  agent summary:", run["agentSummary"][:700])


def main():
    root = Path(sys.argv[1])
    arguments = sys.argv[2:]
    out = arguments[arguments.index("--out") + 1] if "--out" in arguments else None
    notes_path = arguments[arguments.index("--notes") + 1] if "--notes" in arguments else None
    wanted = [word for word in arguments if word.startswith("run_")]
    runs = [build(folder) for folder in sorted(root.iterdir()) if folder.is_dir() and folder.name.startswith("run_") and (folder / "get_run.txt").exists()]
    runs.sort(key=lambda run: run["start"], reverse=True)
    if "--text" in arguments:
        for run in runs:
            if not wanted or run["id"] in wanted:
                report(run)
    if out:
        notes = json.loads(Path(notes_path).read_text(encoding="utf-8")) if notes_path else {}
        for run in runs:
            run["notes"] = notes.get("runs", {}).get(run["id"], {})
        payload = {"runs": runs, "overview": notes.get("overview", {}), "lines": LINES, "max": MAX, "positions": POSITIONS}
        Path(out).write_text("window.REPORT = " + json.dumps(payload, ensure_ascii=False, separators=(",", ":")) + ";\n", encoding="utf-8")
        print(f"wrote {out}: {len(runs)} runs, {Path(out).stat().st_size / 1e6:.2f} MB")


if __name__ == "__main__":
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
    main()

