}

* { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 14px/1.5 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.wrap { max-width: 1240px; margin: 0 auto; padding: 0 20px; }

h1, h2, h3, h4, p { margin: 0; }
h1 { font-size: 16px; font-weight: 600; letter-spacing: -0.01em; }
h2 { font-size: 20px; font-weight: 600; letter-spacing: -0.02em; }
h3 { font-size: 14px; font-weight: 600; }
h4 { font-size: 12px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }

.muted { color: var(--muted); }
.faint { color: var(--faint); }
.small { font-size: 12px; }
.mono { font-family: ui-monospace, SFMono-Regular, "Cascadia Mono", Menlo, Consolas, monospace; font-size: 12px; }
.num { font-variant-numeric: tabular-nums; }
.right { text-align: right; }
.nowrap { white-space: nowrap; }

/* header */
.top { position: sticky; top: 0; z-index: 20; background: color-mix(in srgb, var(--bg) 88%, transparent); backdrop-filter: blur(8px); border-bottom: 1px solid var(--line); }
.top-row { display: flex; align-items: center; gap: 16px; height: 56px; }
.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand p { font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mark { width: 22px; height: 22px; border-radius: 6px; background: var(--text); flex: none; position: relative; }
.mark::after { content: ""; position: absolute; left: 6px; right: 6px; top: 10px; height: 2px; background: var(--bg); box-shadow: 0 -4px 0 var(--bg), 0 4px 0 var(--bg); }

.tabs { display: inline-flex; gap: 2px; padding: 3px; background: var(--soft); border-radius: 8px; margin-left: auto; }
.tab { border: 0; background: transparent; color: var(--muted); padding: 5px 12px; border-radius: 6px; font: inherit; font-weight: 500; cursor: pointer; }
.tab:hover { color: var(--text); }
.tab[aria-selected="true"] { background: var(--bg); color: var(--text); box-shadow: var(--shadow), 0 0 0 1px var(--line); }

.btn { border: 1px solid var(--line); background: var(--bg); color: var(--text); border-radius: 7px; padding: 5px 10px; font: inherit; font-weight: 500; cursor: pointer; }
.btn:hover { background: var(--soft); }
.btn.ghost { border-color: transparent; color: var(--muted); }
.btn.on { background: var(--text); color: var(--bg); border-color: var(--text); }

main { padding-top: 24px; padding-bottom: 48px; }
.foot { padding-bottom: 32px; font-size: 12px; }

/* layout */
.stack { display: grid; gap: 16px; }
.grid { display: grid; gap: 16px; }
.cols-2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.kpis { grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 12px; }
@media (max-width: 1000px) { .cols-2, .cols-3 { grid-template-columns: minmax(0, 1fr); } .kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); } }
@media (max-width: 640px) { .kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); } .top-row { height: auto; flex-wrap: wrap; padding-top: 10px; padding-bottom: 10px; } .tabs { margin-left: 0; order: 3; width: 100%; overflow-x: auto; } .brand p { display: none; } }

.card { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); box-shadow: var(--shadow); min-width: 0; }
.card > .head { padding: 14px 16px 0; display: flex; align-items: baseline; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.card > .head p { font-size: 12px; color: var(--muted); }
.card > .body { padding: 14px 16px 16px; }
.card > .body.flush { padding: 8px 0 4px; }
.scroll { overflow-x: auto; }

.kpi { padding: 14px 16px; }
.kpi .label { font-size: 12px; color: var(--muted); }
.kpi .value { font-size: 22px; font-weight: 600; letter-spacing: -0.02em; font-variant-numeric: tabular-nums; margin-top: 2px; }
.kpi .sub { font-size: 12px; color: var(--muted); margin-top: 2px; }

.section-title { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin: 12px 0 0; flex-wrap: wrap; }
.section-title p { color: var(--muted); font-size: 13px; }

/* badges */
.badge { display: inline-flex; align-items: center; gap: 5px; padding: 1px 8px; border-radius: 999px; font-size: 11.5px; font-weight: 500; border: 1px solid var(--line); background: var(--bg); white-space: nowrap; line-height: 18px; }
.badge.good { background: var(--good-soft); color: var(--good); border-color: transparent; }
.badge.warn { background: var(--warn-soft); color: var(--warn); border-color: transparent; }
.badge.bad { background: var(--bad-soft); color: var(--bad); border-color: transparent; }
.badge.info { background: var(--info-soft); color: var(--info); border-color: transparent; }
.badge.plain { background: var(--soft); color: var(--muted); border-color: transparent; }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; flex: none; }
.line-A { background: var(--a); } .line-B { background: var(--b); } .line-C { background: var(--c); } .line-D { background: var(--d); } .line-E, .line-F, .line-\? { background: var(--e); }

.chip { display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px; border-radius: 6px; border: 1px solid var(--line); font-size: 12px; cursor: pointer; background: var(--bg); color: var(--text); font-family: ui-monospace, SFMono-Regular, Consolas, monospace; }
.chip:hover { background: var(--soft); }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }

/* findings */
.finding { padding: 14px 16px; border-top: 1px solid var(--line); display: grid; grid-template-columns: 28px minmax(0, 1fr) auto; gap: 4px 12px; align-items: start; }
.finding:first-child { border-top: 0; }
.finding .n { width: 22px; height: 22px; border-radius: 6px; background: var(--soft); color: var(--muted); font-size: 12px; font-weight: 600; display: grid; place-items: center; margin-top: 1px; }
.finding .figure { font-size: 12px; font-weight: 600; white-space: nowrap; color: var(--text); background: var(--soft); border-radius: 6px; padding: 2px 8px; }
.finding p { grid-column: 2 / -1; color: var(--muted); font-size: 13px; }
.finding .chips { grid-column: 2 / -1; margin-top: 4px; }
@media (max-width: 640px) { .finding { grid-template-columns: 28px minmax(0, 1fr); } .finding .figure { grid-column: 2; justify-self: start; } }

.bullets { margin: 0; padding: 0; list-style: none; display: grid; gap: 8px; }
.bullets li { padding-left: 16px; position: relative; font-size: 13px; }
.bullets li::before { content: ""; position: absolute; left: 2px; top: 8px; width: 5px; height: 5px; border-radius: 50%; background: var(--faint); }
.bullets.good li::before { background: var(--good); }
.bullets.bad li::before { background: var(--bad); }
.bullets.warn li::before { background: var(--warn); }

/* tables */
table { width: 100%; border-collapse: collapse; font-size: 13px; }
th { text-align: left; font-weight: 500; color: var(--muted); font-size: 12px; padding: 8px 12px; border-bottom: 1px solid var(--line); white-space: nowrap; background: var(--panel); }
td { padding: 8px 12px; border-bottom: 1px solid var(--line); vertical-align: top; }
tr:last-child td { border-bottom: 0; }
th.sort { cursor: pointer; user-select: none; }
th.sort:hover { color: var(--text); }
th.sort[data-dir="asc"]::after { content: " ↑"; }
th.sort[data-dir="desc"]::after { content: " ↓"; }
tbody tr.click { cursor: pointer; }
tbody tr.click:hover { background: var(--softer); }
td.note { color: var(--muted); max-width: 420px; }
td.wraptext { word-break: break-word; }

.toolbar { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; }
.seg { display: inline-flex; border: 1px solid var(--line); border-radius: 7px; overflow: hidden; }
.seg button { border: 0; border-right: 1px solid var(--line); background: var(--bg); color: var(--muted); padding: 5px 10px; font: inherit; font-size: 12.5px; cursor: pointer; }
.seg button:last-child { border-right: 0; }
.seg button:hover { color: var(--text); }
.seg button.on { background: var(--soft); color: var(--text); font-weight: 500; }
input[type="search"], select { border: 1px solid var(--line); background: var(--bg); color: var(--text); border-radius: 7px; padding: 5px 10px; font: inherit; font-size: 13px; min-width: 0; }
input[type="search"]:focus, select:focus, .btn:focus-visible, .tab:focus-visible { outline: 2px solid var(--ring); outline-offset: 1px; }

/* bars */
.bar { display: flex; height: 8px; border-radius: 4px; overflow: hidden; background: var(--soft); min-width: 120px; }
.bar > span { display: block; height: 100%; }
.bar .gather { background: var(--gather); }
.bar .decide { background: var(--decide); }
.bar .submit { background: var(--submit); }
.bar .unknown { background: var(--line); }
.legend { display: flex; flex-wrap: wrap; gap: 12px; font-size: 12px; color: var(--muted); }
.legend i { display: inline-block; width: 10px; height: 10px; border-radius: 3px; margin-right: 5px; vertical-align: -1px; }
.meter { height: 6px; border-radius: 3px; background: var(--soft); overflow: hidden; min-width: 80px; }
.meter > span { display: block; height: 100%; background: var(--text); opacity: 0.75; }

/* score grid */
.score { display: grid; grid-template-columns: 64px repeat(8, minmax(0, 1fr)); gap: 3px; font-size: 11px; }
.score .h { color: var(--muted); padding: 2px 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.score .c { border-radius: 5px; padding: 4px 6px; background: var(--soft); min-height: 26px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-variant-numeric: tabular-nums; }
.score .c.ok { background: var(--good-soft); color: var(--good); }
.score .c.miss { background: var(--bad-soft); color: var(--bad); }
.score .c.none { color: var(--faint); }
@media (max-width: 760px) { .score { grid-template-columns: 48px repeat(8, 56px); overflow-x: auto; } }

/* charts */
svg { display: block; width: 100%; height: auto; }
svg text { fill: var(--muted); font-size: 11px; font-family: inherit; }
svg .axis { stroke: var(--line); stroke-width: 1; }
svg .gridline { stroke: var(--line); stroke-width: 1; stroke-dasharray: 2 3; }
svg .lane { fill: var(--softer); }
svg .lanelabel { fill: var(--text); font-size: 11px; font-weight: 500; }
svg .hit { cursor: pointer; }
.tl-wrap { overflow-x: auto; }
.tl-wrap svg { min-width: 760px; }

.tip { position: fixed; z-index: 50; pointer-events: none; background: var(--text); color: var(--bg); padding: 6px 9px; border-radius: 7px; font-size: 12px; max-width: 380px; line-height: 1.4; box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18); white-space: pre-line; }

.kv { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 4px 14px; font-size: 13px; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; }

.shot { border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.shot img { display: block; width: 100%; height: auto; }
.shot figcaption { padding: 8px 12px; font-size: 12px; color: var(--muted); border-top: 1px solid var(--line); }
figure { margin: 0; }

.empty { padding: 28px 16px; text-align: center; color: var(--muted); }
.logrow.fail td { background: color-mix(in srgb, var(--bad-soft) 55%, transparent); }
.pill-time { font-variant-numeric: tabular-nums; color: var(--muted); white-space: nowrap; }
details > summary { cursor: pointer; color: var(--muted); font-size: 12.5px; padding: 6px 0; }
details[open] > summary { color: var(--text); }
.sub-list { margin: 4px 0 8px; padding: 0; list-style: none; display: grid; gap: 3px; font-size: 12.5px; color: var(--muted); }
.sub-list b { color: var(--text); font-weight: 500; }

(function () {
  "use strict";

  const R = window.REPORT;
  const runs = R.runs;
  const byId = Object.fromEntries(runs.map((run) => [run.id, run]));
  const view = document.getElementById("view");
  const tip = document.getElementById("tip");
  const state = {
    tab: "overview",
    run: runs.find((run) => run.quality === 100) ? runs.find((run) => run.quality === 100).id : runs[0].id,
    outcome: "all",
    line: "all",
    query: "",
    sort: { key: "start", dir: "desc" },
    log: { worker: "all", kind: "all", query: "", all: false },
  };

  const OUTCOME = {
    high: ["35 or more", "good"],
    low: ["under 35", "warn"],
    none: ["no answer", "bad"],
    cancelled: ["cancelled", "plain"],
    platform: ["platform failure", "plain"],
  };
  const FIELD = {
    material_number: "material", quantity: "quantity", base_unit_price: "base price", surcharge_per_unit: "surcharge",
    packaging_per_unit: "packaging", rebate_total: "rebate", unit_price: "unit price", lead_time_weeks: "lead time",
  };

  // ---------------------------------------------------------------- small helpers

  function h(tag, attrs, ...children) {
    const node = document.createElement(tag);
    apply(node, attrs, children);
    return node;
  }

  function s(tag, attrs, ...children) {
    const node = document.createElementNS("http://www.w3.org/2000/svg", tag);
    apply(node, attrs, children);
    return node;
  }

  function apply(node, attrs, children) {
    for (const [key, value] of Object.entries(attrs || {})) {
      if (value === null || value === undefined || value === false) continue;
      if (key === "class") node.setAttribute("class", value);
      else if (key === "text") node.textContent = value;
      else if (key === "tip") node.dataset.tip = value;
      else if (key.startsWith("on")) node.addEventListener(key.slice(2), value);
      else node.setAttribute(key, value);
    }
    for (const child of children.flat(Infinity)) {
      if (child === null || child === undefined || child === false) continue;
      node.append(child.nodeType ? child : document.createTextNode(String(child)));
    }
  }

  const clock = (value) => (value === null || value === undefined ? "–" : `${String(Math.floor(value / 60)).padStart(2, "0")}:${String(Math.floor(value % 60)).padStart(2, "0")}`);
  const money = (value, digits) => "$" + Number(value).toFixed(digits === undefined ? 3 : digits);
  const whole = (value) => Math.round(value).toLocaleString("en-US");
  const short = (id) => id.slice(4, 10);
  const sum = (list, pick) => list.reduce((total, item) => total + pick(item), 0);

  function span(seconds) {
    if (seconds === null || seconds === undefined) return "–";
    const rounded = Math.round(seconds);
    if (rounded < 60) return `${rounded} s`;
    return `${Math.floor(rounded / 60)} min ${rounded % 60} s`;
  }

  function badge(text, kind) {
    return h("span", { class: "badge " + (kind || ""), text });
  }

  function lineBadge(run) {
    return h("span", { class: "badge", tip: R.lines[run.line] || "" }, h("span", { class: "dot line-" + run.line }), "line " + run.line);
  }

  function outcomeBadge(run) {
    const [label, kind] = OUTCOME[run.outcome];
    return badge(label, kind);
  }

  function chip(id) {
    const run = byId[id];
    return h("button", { class: "chip", onclick: () => open(id), tip: run ? `${run.quality === null ? "no score" : "quality " + run.quality} · ${money(run.cost)} · ${clock(run.seconds)}` : "" },
      run ? h("span", { class: "dot line-" + run.line }) : null, short(id));
  }

  function card(title, hint, body, flush) {
    return h("section", { class: "card" },
      title ? h("div", { class: "head" }, h("h3", { text: title }), hint ? h("p", { text: hint }) : null) : null,
      h("div", { class: "body" + (flush ? " flush" : "") }, body));
  }

  function table(columns, rows, options) {
    const head = h("tr", {}, columns.map((column) => h("th", { class: column.right ? "right" : "", text: column.label })));
    const body = rows.map((row) => h("tr", { class: options && options.click ? "click" : "", onclick: options && options.click ? () => options.click(row) : null },
      columns.map((column) => h("td", { class: [column.right ? "right num" : "", column.cls || ""].join(" ").trim() }, column.cell(row)))));
    return h("div", { class: "scroll" }, h("table", {}, h("thead", {}, head), h("tbody", {}, body.length ? body : h("tr", {}, h("td", { colspan: columns.length, class: "empty", text: "Nothing to show." })))));
  }

  function phaseBar(run, scale) {
    const total = scale || run.seconds || 1;
    const part = (seconds, cls, label) => (seconds > 0 ? h("span", { class: cls, style: `width:${(100 * seconds) / total}%`, tip: `${label}: ${span(seconds)}` }) : null);
    const phase = run.phase;
    if (phase.gatherEnd === null || phase.gatherEnd === undefined) {
      return h("div", { class: "bar" }, part(run.seconds, "unknown", "phases not in the kept log"));
    }
    const decided = phase.bidReady === null || phase.bidReady === undefined ? null : Math.max(phase.bidReady, phase.gatherEnd);
    return h("div", { class: "bar" },
      part(phase.gatherEnd, "gather", "gathering"),
      decided === null ? part(run.seconds - phase.gatherEnd, "unknown", "after gathering") : [
        part(decided - phase.gatherEnd, "decide", "deciding"),
        part(Math.max(0, run.seconds - decided), "submit", "submitting"),
      ]);
  }

  function legend(items) {
    return h("div", { class: "legend" }, items.map(([color, label]) => h("span", {}, h("i", { style: `background:${color}` }), label)));
  }

  function open(id) {
    state.run = id;
    state.tab = "run";
    state.log = { worker: "all", kind: "all", query: "", all: false };
    location.hash = "run/" + id;
    render();
    window.scrollTo({ top: 0 });
  }

  // ---------------------------------------------------------------- figures across runs

  function outcomes() {
    const labels = {
      high: "Answer, 35 points or more", low: "Answer, under 35 points", none: "No answer: the agent ended without submitting",
      cancelled: "No answer: cancelled by a teammate", platform: "No answer: platform failure",
    };
    return Object.keys(labels).map((key) => {
      const members = runs.filter((run) => run.outcome === key);
      return { key, label: labels[key], count: members.length, cost: sum(members, (run) => run.cost), seconds: sum(members, (run) => run.seconds) };
    });
  }

  function lines() {
    return Object.keys(R.lines).map((line) => {
      const members = runs.filter((run) => run.line === line);
      if (!members.length) return null;
      const costs = members.map((run) => run.cost).sort((a, b) => a - b);
      const times = members.map((run) => run.seconds).sort((a, b) => a - b);
      return {
        line, name: R.lines[line], count: members.length, answers: members.filter((run) => run.answer).length,
        high: members.filter((run) => run.outcome === "high").length, best: Math.max(...members.map((run) => run.quality || 0)),
        cost: costs[Math.floor(costs.length / 2)], seconds: times[Math.floor(times.length / 2)],
      };
    }).filter(Boolean);
  }

  function lostFields() {
    const scored = runs.filter((run) => run.score);
    const tally = {};
    for (const run of scored) {
      const seen = new Set();
      for (const [name, points] of run.score.lost) {
        const kind = /^\d\d\.\d\d /.test(name) ? name.slice(6) : name;
        tally[kind] = tally[kind] || { kind, runs: 0, points: 0 };
        tally[kind].points += points;
        if (!seen.has(kind)) tally[kind].runs += 1;
        seen.add(kind);
      }
    }
    return { total: scored.length, rows: Object.values(tally).sort((a, b) => b.points - a.points) };
  }

  function repeatedErrors() {
    const tally = {};
    for (const run of runs) {
      for (const [, action, message, count] of run.errors) {
        const key = `${run.line}|${action}|${message.slice(0, 70)}`;
        tally[key] = tally[key] || { line: run.line, action, message, count: 0, runs: new Set() };
        tally[key].count += count;
        tally[key].runs.add(run.id);
      }
    }
    return Object.values(tally).sort((a, b) => b.count - a.count).slice(0, 16);
  }

  // ---------------------------------------------------------------- overview

  function scatter() {
    const points = runs.filter((run) => run.answer && run.quality !== null);
    const W = 560, H = 300, left = 40, right = 14, top = 12, bottom = 34;
    const low = Math.log10(10), high = Math.log10(1000);
    const x = (value) => left + ((Math.log10(Math.max(10, Math.min(1000, value))) - low) / (high - low)) * (W - left - right);
    const y = (value) => top + (1 - value / 100) * (H - top - bottom);
    const svg = s("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "Quality against cost times run time" });
    for (const tick of [0, 25, 50, 75, 100]) {
      svg.append(s("line", { class: "gridline", x1: left, x2: W - right, y1: y(tick), y2: y(tick) }), s("text", { x: left - 6, y: y(tick) + 4, "text-anchor": "end", text: tick }));
    }
    for (const tick of [10, 20, 50, 100, 200, 500, 1000]) {
      svg.append(s("line", { class: "gridline", x1: x(tick), x2: x(tick), y1: top, y2: H - bottom }), s("text", { x: x(tick), y: H - bottom + 14, "text-anchor": "middle", text: tick }));
    }
    svg.append(s("text", { x: (left + W - right) / 2, y: H - 4, "text-anchor": "middle", text: "cost × run time in $·s (log scale; lower is better)" }));
    for (const run of points) {
      const value = run.cost * run.seconds;
      svg.append(s("circle", {
        class: "hit", cx: x(value), cy: y(run.quality), r: 5.5, fill: `var(--${run.line.toLowerCase().replace(/[^abcd]/, "e")})`, "fill-opacity": 0.85, stroke: "var(--bg)", "stroke-width": 1.5,
        tip: `${short(run.id)} · line ${run.line}\nquality ${run.quality} · ${money(run.cost)} · ${clock(run.seconds)} · ${value.toFixed(0)} $·s`, onclick: () => open(run.id),
      }));
      if (run.quality >= 95) svg.append(s("text", { x: x(value) + 8, y: y(run.quality) + 12, text: short(run.id) }));
    }
    return svg;
  }

  function timeChart() {
    const rows = runs.filter((run) => run.phase.gatherEnd !== null && run.phase.gatherEnd !== undefined)
      .sort((a, b) => (b.quality === null ? -1 : b.quality) - (a.quality === null ? -1 : a.quality) || b.seconds - a.seconds);
