  function timeline(run) {
    const T = Math.max(run.seconds, ...run.calls.map((call) => call[0] + call[1]), 60);
    const W = 1100, left = 132, right = 12;
    const x = (value) => left + (Math.max(0, Math.min(T, value)) / T) * (W - left - right);
    const workers = run.workers.slice(0, 14);
    const browsers = Object.entries(run.browsers);
    const lanes = [];
    let y = 8;
    const add = (label, height, kind, data) => { lanes.push({ label, y, height, kind, data }); y += height + 5; };
    add("phases", 12, "phase");
    add("calls in flight", 44, "calls");
    for (const [number, browser] of browsers) add(`browser ${number}${browser.owner ? " · " + browser.owner : ""}`, 12, "browser", browser);
    for (const worker of workers) add(worker.name, 12, "worker", worker);
    const H = y + 20;
    const svg = s("svg", { viewBox: `0 0 ${W} ${H}`, role: "img", "aria-label": "Timeline of the run" });
    const step = T > 1500 ? 300 : T > 600 ? 120 : 60;
    for (let tick = 0; tick <= T; tick += step) {
      svg.append(s("line", { class: "gridline", x1: x(tick), x2: x(tick), y1: 4, y2: H - 18 }), s("text", { x: x(tick), y: H - 5, "text-anchor": "middle", text: clock(tick) }));
    }
    const bucket = Math.max(5, Math.round(T / 220));
    const count = Math.ceil(T / bucket);
    const flight = { qwen: new Array(count).fill(0), clef: new Array(count).fill(0) };
    for (const [start, took, model] of run.calls) {
      const series = model === "qwen" ? flight.qwen : flight.clef;
      for (let index = Math.floor(start / bucket); index <= Math.min(count - 1, Math.floor((start + took) / bucket)); index++) {
        const overlap = Math.min(start + took, (index + 1) * bucket) - Math.max(start, index * bucket);
        if (overlap > 0) series[index] += overlap / bucket;
      }
    }
    const peak = Math.max(1, ...flight.qwen.map((value, index) => value + flight.clef[index]));
    const events = {};
    for (const item of run.events) if (item[1] && ["step", "error", "refused", "stop"].includes(item[2])) (events[item[1]] = events[item[1]] || []).push(item);

    for (const lane of lanes) {
      svg.append(s("rect", { class: "lane", x: left, y: lane.y, width: W - left - right, height: lane.height, rx: 3 }),
        s("text", { class: "lanelabel", x: left - 8, y: lane.y + lane.height / 2 + 4, "text-anchor": "end", text: lane.label.length > 21 ? lane.label.slice(0, 20) + "…" : lane.label }));
      if (lane.kind === "phase") {
        const phase = run.phase;
        const band = (from, to, color, label) => { if (to > from) svg.append(s("rect", { x: x(from), y: lane.y, width: Math.max(1, x(to) - x(from)), height: lane.height, rx: 3, fill: color, tip: `${label}: ${clock(from)} to ${clock(to)} (${span(to - from)})` })); };
