          band(0, phase.gatherEnd, "var(--gather)", "gathering");
          if (phase.bidReady !== null && phase.bidReady !== undefined) {
            const decided = Math.max(phase.bidReady, phase.gatherEnd);
            band(phase.gatherEnd, decided, "var(--decide)", "deciding");
