      } else if (lane.kind === "calls") {
        for (let index = 0; index < count; index++) {
          const width = Math.max(1, x((index + 1) * bucket) - x(index * bucket) - 0.6);
          const qwen = (flight.qwen[index] / peak) * lane.height, clef = (flight.clef[index] / peak) * lane.height;
          const label = `${clock(index * bucket)}: ${flight.qwen[index].toFixed(1)} Qwen and ${flight.clef[index].toFixed(1)} Clef calls in flight`;
          if (qwen > 0.2) svg.append(s("rect", { x: x(index * bucket), y: lane.y + lane.height - qwen, width, height: qwen, fill: "var(--qwen)", tip: label }));
          if (clef > 0.2) svg.append(s("rect", { x: x(index * bucket), y: lane.y + lane.height - qwen - clef, width, height: clef, fill: "var(--clef)", tip: label }));
        }
        svg.append(s("text", { x: W - right - 4, y: lane.y + 11, "text-anchor": "end", text: `peak ${peak.toFixed(1)}` }));
      } else if (lane.kind === "browser") {
