    if (keepScroll) window.scrollTo({ top: at });
  }

  function route() {
    const [tab, id] = location.hash.replace(/^#/, "").split("/");
    if (["overview", "runs", "stuck", "run"].includes(tab)) state.tab = tab;
    if (tab === "run" && byId[id]) state.run = id;
    render();
  }

  document.getElementById("tabs").addEventListener("click", (event) => {
    const tab = event.target.closest(".tab");
    if (!tab) return;
    location.hash = tab.dataset.tab === "run" ? "run/" + state.run : tab.dataset.tab;
  });
  window.addEventListener("hashchange", route);

  document.addEventListener("mousemove", (event) => {
    const target = event.target.closest && event.target.closest("[data-tip]");
    if (!target || !target.dataset.tip) { tip.hidden = true; return; }
    tip.textContent = target.dataset.tip;
    tip.hidden = false;
    const box = tip.getBoundingClientRect();
    tip.style.left = Math.max(8, Math.min(window.innerWidth - box.width - 8, event.clientX + 14)) + "px";
    tip.style.top = (event.clientY + box.height + 24 > window.innerHeight ? event.clientY - box.height - 12 : event.clientY + 16) + "px";
  });

  const themeButton = document.getElementById("theme");
  function setTheme(name) {
    document.documentElement.dataset.theme = name;
    themeButton.textContent = name === "dark" ? "Light" : "Dark";
    try { localStorage.setItem("run-report-theme", name); } catch (error) { /* storage can be blocked for local files */ }
  }
  let saved = null;
  try { saved = localStorage.getItem("run-report-theme"); } catch (error) { saved = null; }
  setTheme(saved || (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light"));
  themeButton.addEventListener("click", () => setTheme(document.documentElement.dataset.theme === "dark" ? "light" : "dark"));

  document.getElementById("subtitle").textContent = `${runs.length} runs · ${R.overview.asOf} · rfq challenge`;
