170	@dataclass
171	class Control:
172	    id: int
173	    kind: str
174	    label: str
175	    frame: int
176	    href: str = ""
177	    extra: str = ""
178	    value: str | None = None
179	    options: list[str] | None = None
180	    checked: bool | None = None
181	    disabled: bool = False
182	    readonly: bool = False
