184	
185	    @property
186	    def fillable(self) -> bool:
187	        return not self.disabled and not self.readonly and self.kind in (
188	            "input", "search", "email", "number", "tel", "password", "textarea", "textbox", "searchbox", "select",
189	            "range", "checkbox", "radio", "date", "datetime-local", "combobox", "slider", "switch")
190	
191	    def describe(self) -> str:
192	        text = f"{self.kind} '{self.label}'{self.extra}"
193	        return text + (f" (row: {self.context})" if self.context else "")
