196	@dataclass
197	class Observation:
198	    url: str
199	    title: str
200	    text: str
201	    controls: dict[int, Control] = field(default_factory=dict)
202	    password: bool = False
203	
204	    @property
205	    def signature(self) -> str:
206	        body = re.sub(r"\[\d+:", "[", self.text)
207	        return hashlib.sha1((self.url.split("#")[0] + body).encode()).hexdigest()[:16]
208	
209	    def clip(self, limit: int) -> str:
210	        head = f"URL: {self.url}\nTitle: {self.title}\n"
211	        return head + (self.text if len(self.text) <= limit else self.text[:limit] + "\n[… page text truncated]")
