213	
214	def text_of_document(name: str, data: bytes, limit: int = 20000) -> str:
215	    """Text of a downloaded document the model chose: ZIP members, text formats and (if available) PDFs."""
216	    lower = name.lower()
217	    if lower.endswith(".zip") or data[:2] == b"PK":
218	        parts = []
219	        with zipfile.ZipFile(io.BytesIO(data)) as archive:
220	            for member in archive.namelist():
221	                if not member.endswith("/"):
222	                    parts.append(f"--- {member}\n" + text_of_document(member, archive.read(member), limit // 2))
223	        return "\n".join(parts)[:limit]
224	    if lower.endswith(".pdf") or data[:4] == b"%PDF":
225	        try:
226	            from pypdf import PdfReader  # optional; present only if installed
227	            return "\n".join(page.extract_text() or "" for page in PdfReader(io.BytesIO(data)).pages)[:limit]
228	        except Exception as error:
229	            return f"[PDF {name}: no text extracted ({type(error).__name__}); open it in the browser instead]"
230	    for encoding in ("utf-8", "cp1252", "latin-1"):
231	        try:
232	            text = data.decode(encoding)
233	            break
234	        except UnicodeDecodeError:
235	            continue
236	    if lower.endswith((".html", ".htm")) or "<html" in text[:500].lower():
237	        text = re.sub(r"<(script|style)[^>]*>.*?</\1>", " ", text, flags=re.S | re.I)
238	        text = re.sub(r"<br\s*/?>|</(p|div|tr|li|h\d)>", "\n", text, flags=re.I)
239	        text = re.sub(r"<[^>]+>", " ", text)
240	    return re.sub(r"[ \t]+", " ", text)[:limit]
