243	class Tab:
244	    """One website's browser context: the page a worker drives plus helpers for model-chosen actions."""
245	
246	    def __init__(self, site: dict, context, page, log=print):
247	        self.site = site
248	        self.context = context
249	        self.page = page
250	        self.log = log
251	        self.obs: Observation | None = None
252	        self.events: list[str] = []  # dialogs, downloads and popups since the last observation
253	        self.host = urlparse(site["url"]).netloc
254	        if page is not None:  # None: the tab's page is opened later with open()
255	            self._watch(page)
256	
257	    # ---------------------------------------------------------------- events
258	    def _watch(self, page):
259	        page.on("dialog", self._on_dialog)
260	        page.on("download", lambda download: asyncio.ensure_future(self._on_download(download)))
261	        page.on("popup", self._on_popup)
262	
263	    async def _on_dialog(self, dialog):
264	        self.events.append(f"browser {dialog.type} dialog '{dialog.message[:200]}' was accepted")
265	        try:
266	            await dialog.accept()
267	        except Exception:
268	            pass
269	
270	    async def _on_download(self, download):
271	        try:
272	            path = await download.path()
273	            data = open(path, "rb").read() if path else b""
274	            self.events.append(f"downloaded {download.suggested_filename}:\n" + text_of_document(download.suggested_filename, data))
275	        except Exception as error:
276	            self.events.append(f"download {download.suggested_filename} failed: {error}")
277	
278	    def _on_popup(self, popup):
279	        self.events.append("a new window opened and is now the active page")
280	        self._watch(popup)
281	        self.page = popup
282	
283	    async def open(self, url: str) -> str:
284	        """Open this tab's own page in its context (sharing the session) and load `url` there."""
285	        self.page = await self.context.new_page()
286	        self._watch(self.page)
287	        await self.page.set_viewport_size({"width": 1280, "height": 800})
288	        return await self.goto(url if url.startswith("http") else self.site["url"])
289	
290	    # ------------------------------------------------------------ observing
291	    async def observe(self) -> Observation:
292	        if self.page.is_closed():
293	            open_pages = [p for p in self.context.pages if not p.is_closed()]
294	            self.page = open_pages[-1] if open_pages else await self.context.new_page()
295	        obs = await self._render(self.page)
296	        if self.events:
297	            obs.text = "\n".join(f"[event: {e[:3000]}]" for e in self.events) + "\n" + obs.text
298	            self.events.clear()
299	        self.obs = obs
300	        return obs
301	
302	    async def _render(self, page) -> Observation:
303	        parts, controls, password, next_id, title = [], {}, False, 1, ""
304	        for index, frame in enumerate(page.frames):
305	            if frame.is_detached() or (index and frame.url in ("", "about:blank")):
306	                continue
307	            try:
308	                result = await asyncio.wait_for(frame.evaluate(OBSERVE_JS, next_id), 8)
309	            except Exception:
310	                continue
311	            next_id = result["next"]
312	            password = password or result["password"]
313	            if index == 0:
314	                title = result["title"]
315	                parts.append(result["text"])
316	            elif result["text"].strip():
317	                parts.append(f"--- frame {frame.url.replace('https://' + self.host, '')}\n{result['text']}")
318	            for item in result["controls"]:
319	                controls[item["id"]] = Control(
320	                    id=item["id"], kind=item["kind"], label=item["label"], frame=index, href=item.get("href", ""),
321	                    extra=item.get("extra", ""), value=item.get("value"), options=item.get("options"),
322	                    checked=item.get("checked"), disabled=bool(item.get("disabled")), readonly=bool(item.get("readonly")))
323	        text = "\n".join(parts)
324	        for line in text.splitlines():
325	            ids = [int(m) for m in re.findall(r"\[(\d+):", line)]
326	            context = re.sub(r"\s+", " ", re.sub(r"\[\d+:[^\]]*\]", " ", line)).strip()[:90]
327	            for cid in ids:
328	                if cid in controls:
329	                    controls[cid].context = context
330	        return Observation(url=page.url, title=title, text=text, controls=controls, password=password)
331	
332	    def _locate(self, cid: int):
333	        control = self.obs.controls.get(cid) if self.obs else None
334	        if control is None:
335	            raise ValueError(f"control {cid} is not on the current page; observe again")
336	        frames = self.page.frames
337	        frame = frames[control.frame] if control.frame < len(frames) else self.page.main_frame
338	        return control, frame.locator(f'[data-aid="{cid}"]').first
339	
340	    # -------------------------------------------------------------- actions
341	    async def settle(self, before: str | None = None):
342	        """Wait briefly for the navigation or DOM update an action started."""
343	        await asyncio.sleep(0.25)
344	        for _ in range(2):
345	            try:
346	                await self.page.wait_for_load_state("domcontentloaded", timeout=6000)
347	            except Exception:
348	                pass
349	            for frame in self.page.frames[1:]:
350	                try:
351	                    await frame.wait_for_load_state("domcontentloaded", timeout=3000)
352	                except Exception:
353	                    pass
354	            if before is None or self.page.url != before:
355	                break
356	            await asyncio.sleep(0.2)
357	        await self._retry_error_page()
358	
359	    async def _retry_error_page(self):
360	        """Flaky server errors: reload a page whose main document came back with a 5xx status, at most twice."""
361	        for _ in range(2):
362	            try:
363	                status = await asyncio.wait_for(self.page.evaluate(
364	                    "() => (performance.getEntriesByType('navigation')[0] || {}).responseStatus || 0"), 3)
365	            except Exception:
366	                return
367	            if not status or status < 500:
368	                return
369	            self.log(f"[{self.site['siteId']}] server error {status}; reloading")
370	            await asyncio.sleep(0.4)
371	            try:
372	                await self.page.reload(wait_until="domcontentloaded", timeout=10000)
373	            except Exception:
374	                return
