378	        if control.disabled and control.href:  # a locked overlay disables the link, not its target
379	            await self.goto(control.href)
380	            return f"opened the target of {control.describe()[:120]}"
381	        before = self.page.url
382	        try:
383	            await locator.evaluate(OPEN_DETAILS_JS, timeout=3000)
384	            await locator.click(timeout=3000)
385	        except Exception:
386	            try:
387	                await locator.evaluate("e => e.click()", timeout=3000)
388	            except Exception:
